public class RuntimeUtilsTest extends DBeaverUnitTest {

    @Test
    public void testCurrentDateTimeFormats() {
        Assertions.assertTrue(RuntimeUtils.getCurrentDate().matches("\\d{8}"));
        Assertions.assertTrue(RuntimeUtils.getCurrentTime().matches("\\d{6}"));
        Assertions.assertTrue(RuntimeUtils.getCurrentTimeStamp().matches("\\d{12}"));
    }

    @Test
    public void testLocalPathFromURL(@TempDir Path tempDir) throws Exception {
        Path file = Files.createFile(tempDir.resolve("sample file.txt"));

        Assertions.assertEquals(file, RuntimeUtils.getLocalFileFromURL(file.toUri().toURL()));
        Assertions.assertEquals(file, RuntimeUtils.getLocalPathFromURL(file.toUri().toURL()));
    }

    @Test
    public void testStripStackAddsExceptionClassWhenMessageIsEmpty() {
        IStatus status = new Status(IStatus.ERROR, "test.plugin", "failure", new RuntimeException());

        IStatus stripped = RuntimeUtils.stripStack(status);

        Assertions.assertEquals("java.lang.RuntimeException: failure", stripped.getMessage());
        Assertions.assertNull(stripped.getException());
    }

    @Test
    public void testStripStackProcessesMultiStatusChildren() {
        IStatus child = new Status(IStatus.ERROR, "test.plugin", "child failure", new RuntimeException());
        IStatus status = new MultiStatus("test.plugin", 0, new IStatus[]{child}, "parent failure", new RuntimeException());

        IStatus stripped = RuntimeUtils.stripStack(status);

        Assertions.assertNull(stripped.getException());
        Assertions.assertEquals("java.lang.RuntimeException: child failure", stripped.getChildren()[0].getMessage());
        Assertions.assertNull(stripped.getChildren()[0].getException());
    }

    @Test
    public void testSplitCommandLine() {
        Assertions.assertEquals(Arrays.asList("/bin/sh", "-c", "echo hello && echo world"), RuntimeUtils.splitCommandLine("/bin/sh -c 'echo hello && echo world'", true));
    }

    @Test
    public void testBackslashPath() {
        Assertions.assertEquals(Collections.singletonList("C:\\Windows\\notepad.exe"), RuntimeUtils.splitCommandLine("C:\\Windows\\notepad.exe", false));
        Assertions.assertEquals(Collections.singletonList("C:\\Windows\\notepad.exe"), RuntimeUtils.splitCommandLine("C:\\\\Windows\\\\notepad.exe", true));
    }

    @Test
    public void testBackslashEscape() {
        Assertions.assertEquals(Arrays.asList("ls", "-l", "/home/folder with spaces"), RuntimeUtils.splitCommandLine("ls -l /home/folder\\ with\\ spaces", true));
        Assertions.assertEquals(Arrays.asList("ls", "-l", "/home/\"folder with quotes\""), RuntimeUtils.splitCommandLine("ls -l /home/\\\"folder\\ with\\ quotes\\\"", true));
    }
